 ('mc', 5, 'bayram_oruc', 'Bayramda oruç', 'm', 'Bayram günlerinde oruç tutmak hakkında hüküm nedir?', 'Bayramın ilk günü oruç tutmak yasaktır', ['Bayramda oruç farzdır', 'Bayramda iki gün oruç gerekir', 'Bayram orucu Ramazan’dan sevaplıdır'], 'Hz. Peygamber iki bayram gününde oruç tutmayı yasakladı (Buhârî).'),
 ('mc', 5, 'sevval_alti', 'Şevval orucu', 'm', 'Hadise göre Ramazan’dan sonra Şevval’de kaç gün oruç tutan bütün yılı oruçlu geçirmiş gibi olur?', 'Altı gün', ['İki gün', 'On gün', 'Otuz gün'], '“Ramazan’ı tutup ardından Şevval’den altı gün oruç tutan, bütün yılı oruçlu geçirmiş gibidir.” (Müslim)'),
 ('mc', 5, 'arefe_orucu', 'Arefe orucu', 'h', 'Hac yapmayanlar için arefe günü orucu hakkında hadiste ne bildirilir?', 'Önceki ve sonraki yılın günahlarına kefaret olduğu umulur', ['Tutulması yasaktır', 'Hiçbir faydası yoktur', 'Sadece hacılar tutabilir'], 'Arefe orucu iki yılın günahlarına kefaret olur (Müslim).'),
 ('mc', 5, 'pazartesi_persembe', 'Haftalık oruç', 'm', 'Hz. Peygamber haftanın hangi iki gününde nafile oruç tutmayı severdi?', 'Pazartesi ve perşembe', ['Cuma ve cumartesi', 'Salı ve çarşamba', 'Cumartesi ve pazar'], '“Ameller pazartesi ve perşembe günleri arz edilir; amelimin oruçlu iken arz edilmesini severim.” (Tirmizî)'),
 ('mc', 5, 'eyyam_biz', 'Beyaz günler', 'h', 'Her kamerî ayın 13, 14 ve 15. günlerine ne denir?', 'Eyyâm-ı bîz (beyaz günler)', ['Haram aylar', 'Teşrik günleri', 'Üç aylar'], 'Ay’ın dolunay olduğu bu günlerde oruç tutmak tavsiye edilir (Nesâî).'),
 ('tf', 5, 'kurban_dort', 'Kurban günleri', 'm', 'Kurban Bayramı dört gündür.', True, 'Kurban Bayramı Zilhicce’nin 10, 11, 12 ve 13. günleridir.'),
 ('tf', 5, 'bayram_dogum', 'Bayram ve doğum', 'm', 'Ramazan Bayramı, Hz. Peygamber’in doğumunu kutlamak için konulmuştur.', False, 'Ramazan Bayramı, Ramazan orucunun tamamlanmasının sevincidir.'),
 ('mi', 5, 'mi_bayram_tekbir', 'Tekbir', 'm', 'Bakara 185’e göre orucu tamamlayınca Allah’ı ___ için tekbir getiririz.', 'doğru yola ilettiği', ['zengin ettiği', 'meşhur ettiği', 'yorduğu'], 'Bakara 2:185: Sizi doğru yola ilettiği için Allah’ı tekbir edesiniz diye.'),
 ('fb', 5, 'fb_tesrik', 'Teşrik tekbiri', 'h', 'Kurban Bayramı’nda farz namazlardan sonra getirilen tekbirlere ___ tekbiri denir.', 'teşrik', ['iftar', 'teravih', 'sahur'], 'Teşrik tekbirleri arefe sabahından bayramın dördüncü günü ikindiye kadar getirilir.'),
 ('pr', 5, 'pr_fitr', 'Ramazan Bayramı', 'm', 'Ramazan Bayramı’nın diğer adı Îdü’l-___ dır.', 'Fıtr', 'Fıtr, orucu açmak demektir.'),
 ('mt', 5, 'oruc_esle', 'Nafile oruçlar', 'h', 'Oruçları zamanlarıyla eşleştir:', [('Âşûrâ orucu', 'Muharrem’in 10. günü'), ('Arefe orucu', 'Zilhicce’nin 9. günü'), ('Şevval orucu', 'Bayramdan sonra altı gün'), ('Beyaz günler', 'Ayın 13, 14 ve 15. günleri')], 'Ramazan dışında da tavsiye edilen nafile oruçlar vardır.'),
 ('sc', 5, 'sc_bayram_ziyaret', 'Bayram adabı', 'e', 'Bayram sabahı nasıl davranmak sünnete uygundur?', 'Temizlenip güzel giyinmek, bayram namazına gitmek ve büyükleri ziyaret etmek', ['Bütün gün uyumak', 'Kimseyle bayramlaşmamak', 'Küslükleri sürdürmek'], 'Hz. Peygamber bayramlarda güzel elbiselerini giyerdi; bayram sevinç ve kaynaşma günüdür.'),
 ('es', 5, 'es_kurban_sevval', 'Kurban zamanı', 'm', 'Kurban Bayramı Şevval ayındadır.', 'Kurban Bayramı Zilhicce ayındadır', ['Kurban Bayramı Ramazan’dadır', 'Kurban Bayramı Muharrem’dedir', 'Kurban Bayramı Recep’tedir'], 'Kurban Bayramı 10 Zilhicce’de başlar; Şevval’de Ramazan Bayramı vardır.'),

