 ('sr', 6, 'sr_kadir', 'Kadir', 'm', 'Kadir gecesi ne kadar zamandan daha hayırlıdır?', 'Bin aydan', ['Bir haftadan', 'Bir yıldan', 'On günden'], 'Kadr 97:3.'),
 ('sr', 6, 'sr_asure', 'Âşûrâ', 'm', 'Âşûrâ günü hangi ayın onuncu günüdür?', 'Muharrem', ['Ramazan', 'Zilhicce', 'Şaban'], 'Âşûrâ Muharrem’in onuncu günüdür.'),
 ('tf', 6, 'tf_tekrar_354', 'Yıl', 'm', 'Kamerî yıl, güneş yılından uzundur.', False, 'Kamerî yıl yaklaşık 354 gündür; güneş yılından yaklaşık 11 gün kısadır.'),
 ('tf', 6, 'tf_tekrar_mirac_namaz', 'Miraç', 'm', 'Beş vakit namaz Miraç’ta farz kılındı.', True, 'Mi‘râc gecesinde beş vakit namaz farz kılındı (Buhârî).'),
 ('tf', 6, 'tf_tekrar_sevval', 'Şevval', 'e', 'Ramazan Bayramı Şevval ayının ilk günüdür.', True, '1 Şevval Ramazan Bayramı’dır.'),
 ('mc', 6, 'mc_tekrar_arefe', 'Arefe', 'm', 'Arefe günü Zilhicce’nin kaçıncı günüdür?', '9.', ['1.', '15.', '27.'], 'Arefe, Kurban Bayramı’ndan önceki gündür.'),
 ('mc', 6, 'mc_tekrar_alti', 'Şevval orucu', 'm', 'Şevval’de tavsiye edilen nafile oruç kaç gündür?', 'Altı', ['Üç', 'On', 'Kırk'], 'Müslim’de geçen hadise göre altı gündür.'),
 ('mc', 6, 'mc_tekrar_haram', 'Haram aylar', 'h', 'Aşağıdakilerden hangisi haram aylardan biri değildir?', 'Ramazan', ['Muharrem', 'Recep', 'Zilkade'], 'Haram aylar: Zilkade, Zilhicce, Muharrem ve Recep.'),
 ('es', 6, 'es_tekrar_ay_30', 'Ay uzunluğu', 'm', 'Kamerî aylar her zaman 31 gündür.', 'Kamerî aylar 29 veya 30 gündür', ['Kamerî aylar 25 gündür', 'Kamerî aylar 35 gündür', 'Kamerî ayların uzunluğu yoktur'], 'Ay hilalin görünmesine göre 29 ya da 30 gün çeker.'),
 ('es', 6, 'es_tekrar_teravih', 'Teravih', 'm', 'Teravih namazı bayram sabahı kılınır.', 'Teravih namazı Ramazan gecelerinde yatsıdan sonra kılınır', ['Teravih cuma öğlen kılınır', 'Teravih Muharrem’de kılınır', 'Teravih sadece hacda kılınır'], 'Bayram sabahı kılınan namaz bayram namazıdır.'),

 # S7 — Ünite Challenge (14)
 ('mc', 7, 'ch_ramazan_kis', 'Mevsimler', 'h', 'Bir kişi hayatı boyunca Ramazan’ı hem yazın hem kışın tutabilir. Bunun sebebi nedir?', 'Kamerî takvim güneş yılına göre her yıl kaydığı için', ['Ramazan’ın tarihi her yıl kurayla belirlendiği için', 'Ramazan’ın kaç gün olduğu belli olmadığı için', 'Her ülkede farklı ayda tutulduğu için'], 'Yaklaşık 33 yılda Ramazan bütün mevsimleri dolaşır.'),
 ('mc', 7, 'ch_gece_baslar', 'Mübarek gece', 'h', 'Ramazan’ın 27. günü perşembeye denk geliyorsa, 27. gece olarak ihya edilen Kadir gecesi ne zaman başlar?', 'Çarşamba akşamı güneş batınca', ['Perşembe akşamı güneş batınca', 'Perşembe öğlen', 'Cuma sabahı'], 'Hicrî takvimde gün akşamla başladığı için bir günün gecesi, o günden önceki akşam başlar.'),
 ('mc', 7, 'ch_ayet_hilal', 'Ayet', 'm', 'Hilallerin vakit ölçüsü olduğunu bildiren ayet hangisidir?', 'Bakara 2:189', ['Kadr 97:1', 'İsrâ 17:1', 'Fâtiha 1:1'], 'Bakara 2:189: Onlar insanlar ve hac için vakit ölçüleridir.'),
 ('mc', 7, 'ch_ayet_kadir', 'Kadir suresi', 'm', 'Kur’an’ın Kadir gecesinde indirildiğini bildiren sure hangisidir?', 'Kadr suresi', ['Fil suresi', 'Kevser suresi', 'Nas suresi'], 'Kadr 97:1: Biz onu Kadir gecesinde indirdik.'),
 ('es', 7, 'ch_es_asure_isa', 'Âşûrâ', 'h', 'Hadise göre Âşûrâ günü Hz. İsa göğe yükseltildiği için oruç tutulur.', 'Hadise göre Âşûrâ günü Hz. Musa ve kavmi Firavun’dan kurtarıldı', ['Âşûrâ günü Kâbe inşa edildi', 'Âşûrâ günü Hz. Peygamber doğdu', 'Âşûrâ günü Bedir savaşı oldu'], 'Hz. Peygamber şükür olarak bu günü oruçla geçirdi (Buhârî).'),
 ('es', 7, 'ch_es_kadir_belli', 'Kadir', 'h', 'Kadir gecesinin Ramazan’ın ilk gecesi olduğu kesindir.', 'Kadir gecesi kesin bilinmez; son on gecenin teklerinde aranır', ['Kadir gecesi Şaban’ın ilk gecesidir', 'Kadir gecesi her cuma gecesidir', 'Kadir gecesi hiç yoktur'], 'Kesin tarihin gizli tutulması, bütün geceleri değerlendirmeye teşvik eder.'),
 ('pr', 7, 'ch_pr_asure', 'Onuncu gün', 'm', 'Muharrem’in onuncu gününe ___ günü denir.', 'Âşûrâ', 'Âşûrâ, onuncu anlamına gelir.'),
 ('pr', 7, 'ch_pr_arefe', 'Dokuzuncu gün', 'm', 'Zilhicce’nin dokuzuncu gününe ___ günü denir.', 'arefe', 'Hacılar arefe günü Arafat’ta bulunur.'),
 ('pr', 7, 'ch_pr_isra', 'Yolculuk', 'h', 'Mescid-i Harâm’dan Mescid-i Aksâ’ya gece yolculuğunu anlatan sure ___ suresidir.', 'İsrâ', 'İsrâ 17:1 bu yolculuğu anlatır.'),
 ('mc', 7, 'ch_sira', 'Sıralama', 'h', 'Aşağıdakilerden hangisi ayların doğru sırasıdır?', 'Recep, Şaban, Ramazan, Şevval', ['Şaban, Recep, Şevval, Ramazan', 'Ramazan, Şaban, Recep, Şevval', 'Şevval, Ramazan, Recep, Şaban'], 'Recep 7., Şaban 8., Ramazan 9., Şevval 10. aydır.'),
 ('mt', 7, 'ch_mt_gun', 'Tarihler', 'h', 'Günleri tarihleriyle eşleştir:', [('Hicrî yılbaşı', '1 Muharrem'), ('Ramazan Bayramı', '1 Şevval'), ('Arefe', '9 Zilhicce'), ('Kurban Bayramı', '10 Zilhicce')], 'Bu tarihler hicrî takvime göredir.'),
 ('mt', 7, 'ch_mt_isim', 'İsimler', 'm', 'Arapça isimleri anlamlarıyla eşleştir:', [('Hilal', 'Yeni ayın ilk görüntüsü'), ('Fıtr', 'Orucu açma'), ('Adhâ', 'Kurban'), ('Âşûrâ', 'Onuncu')], 'İsimlerin anlamları günlerin özünü anlatır.'),
 ('sc', 7, 'ch_bayram_paylas', 'Paylaşmak', 'm', 'Bayramda sınıfında yalnız kalan, ailesi uzakta olan bir arkadaşın var. Ne yaparsın?', 'Onu bayramlaşmaya ve evimize davet ederim', ['Onu görmezden gelirim', 'Bayramın bitmesini beklerim', 'Onunla dalga geçerim'], 'Bayram sevinci paylaşıldıkça çoğalır; yalnız olanları gözetmek güzel ahlaktır.'),
 ('tf', 7, 'ch_tf_teravih', 'Teravih', 'm', 'Teravih namazı Ramazan ayına özgüdür.', True, 'Teravih yalnızca Ramazan gecelerinde kılınır.'),
